\title{Primitive Prime Divisors of Fibonacci Numbers: Entry Points,
Lifting-the-Exponent, and a Formal Treatment of Carmichael's Theorem}

\author{Aristotle (Harmonic)}
\date{2026-06-15}

\begin{document}

\begin{abstract}
We present a self-contained development of the theory of primitive prime
divisors of the Fibonacci sequence $F_n$, culminating in Carmichael's 1913
theorem: for every index $n \notin \{1,2,6,12\}$ the Fibonacci number $F_n$
possesses a primitive prime divisor, i.e.\ a prime dividing $F_n$ but none of
$F_1,\dots,F_{n-1}$. The development rests on three pillars: the strong
divisibility property $\gcd(F_m,F_n)=F_{\gcd(m,n)}$ and the entry-point
characterization $p \mid F_n \iff z(p)\mid n$; a lifting-the-exponent (LTE)
lemma $\vp(F_{nk})=\vp(F_k)+\vp(n)$ for odd primes $p \mid F_k$ with $p \nmid n$;
and exponential growth bounds $F_n \ge 2^{\lfloor (n-2)/2\rfloor}$. We give an
unconditional proof for prime indices, a complete determination of the
exceptional set, an entry-point localization $z(p) \mid p^2-1$ via the companion
matrix over a finite field, and the simultaneous-apparition calculus for several
primitive divisors. All results have been formally verified in the Lean~4 proof
assistant on top of Mathlib; here we give the mathematics and proof sketches.
\end{abstract}

\maketitle

\section{Introduction}

The Fibonacci sequence is defined by $F_0=0$, $F_1=1$, and $F_{n+2}=F_{n+1}+F_n$.
Its arithmetic is richly structured, and one striking structural fact concerns
the \emph{first appearance} of prime factors.

\begin{definition}[Primitive prime divisor]
A prime $p$ is a \emph{primitive prime divisor} of $F_n$ if $p \mid F_n$ and
$p \nmid F_k$ for all $1 \le k < n$.
\end{definition}

\begin{theorem}[Carmichael, 1913]
For every $n \notin \{1,2,6,12\}$, $F_n$ has a primitive prime divisor.
Equivalently $F_n$ has a primitive prime divisor for all $n \ge 13$ together with
$n \in \{3,4,5,7,8,9,10,11\}$, and fails only at $n \in \{1,2,6,12\}$.
\end{theorem}

This paper assembles, in a uniform elementary style, the quantitative machinery
behind this theorem: the entry-point characterization, the lifting-the-exponent
lemma, growth bounds, and the finite-field localization of entry points. The
formalization was carried out in Lean~4/Mathlib; here we present statements and
proof sketches.

\section{Elementary properties and growth bounds}

We work with $F:\mathbb{N}\to\mathbb{N}$, $F_0=0$, $F_1=1$, $F_{n+2}=F_{n+1}+F_n$.

\begin{lemma}[Positivity]
$F_n > 0$ for all $n > 0$.
\end{lemma}

\begin{lemma}[Strict monotonicity]
If $2 \le m < n$ then $F_m < F_n$.
\end{lemma}

\begin{lemma}[Index domination]
$F_n \ge n$ for all $n \ge 5$.
\end{lemma}

\begin{proof}[Proof sketch]
Strong induction: base cases $n=5,\dots,9$ are direct, and the step uses
$F_{n+2}=F_{n+1}+F_n \ge (n+1)+n \ge n+2$.
\end{proof}

\begin{lemma}[Exponential lower bound]\label{lem:exp}
For all $n \ge 2$, $\;2^{\lfloor (n-2)/2 \rfloor} \le F_n.$
\end{lemma}

\begin{proof}[Proof sketch]
Split on parity $n=2k$ or $n=2k+1$ and induct, using $F_{m+2}=F_{m+1}+F_m \ge
2F_m$ to double across two steps. This is the golden-ratio growth
$F_n=\Theta(\varphi^n)$ in certificate-friendly form.
\end{proof}

\begin{lemma}[Multiplicative bound]
For $m,n \ge 1$, $\;F_m F_n \le F_{m+n}.$
\end{lemma}

\begin{proof}[Proof sketch]
Induct on $n$ using the addition formula $F_{m+n}=F_m F_{n-1}+F_{m+1}F_n$; the
cross terms are nonnegative and $F_{m+1}F_n \ge F_m F_n$.
\end{proof}

\section{The entry point and divisibility characterization}

\begin{theorem}[Strong divisibility]\label{thm:sdiv}
For all $m,n$, $\;\gcd(F_m,F_n)=F_{\gcd(m,n)}.$
\end{theorem}

\begin{proof}[Proof sketch]
This is \texttt{Nat.fib\_gcd}. It follows from $Q^n=\left(\begin{smallmatrix}
F_{n+1}&F_n\\F_n&F_{n-1}\end{smallmatrix}\right)$, the addition formula, and the
Euclidean algorithm on indices.
\end{proof}

\begin{corollary}\label{cor:dvd}
If $m \mid n$ then $F_m \mid F_n$.
\end{corollary}

\begin{proposition}[Meet law]
For all $d,m,n$: $\;d \mid F_{\gcd(m,n)} \iff d \mid F_m \text{ and } d \mid F_n.$
\end{proposition}

\begin{definition}[Entry point]
For $p \ge 2$, the \emph{entry point} (rank of apparition) is
$z(p)=\min\{k>0 : p \mid F_k\}$ when such $k$ exists, and $z(p)=0$ otherwise.
\end{definition}

\begin{theorem}[Entry-point characterization]\label{thm:char}
Let $p$ be prime with $\exists k>0,\ p \mid F_k$, and let $n>0$. Then
$\;p \mid F_n \iff z(p) \mid n.$
\end{theorem}

\begin{proof}[Proof sketch]
($\Leftarrow$) $z(p)\mid n \Rightarrow F_{z(p)} \mid F_n$ (Corollary~\ref{cor:dvd})
and $p \mid F_{z(p)}$. ($\Rightarrow$) With $g=\gcd(z(p),n)$, Theorem~\ref{thm:sdiv}
gives $\gcd(F_{z(p)},F_n)=F_g$, so $p \mid F_g$; minimality of $z(p)$ and $g \le
z(p)$ force $g=z(p)$, i.e.\ $z(p)\mid n$.
\end{proof}

\section{Primitive prime divisors and rigidity}

\begin{definition}
A prime $p$ is a \emph{primitive prime divisor} of $F_n$ if $p$ is prime, $p \mid
F_n$, and $p \nmid F_k$ for all $0<k<n$. We say $F_n$ \emph{has} a primitive
prime divisor if such $p$ exists.
\end{definition}

\begin{theorem}[Primitivity equals entry point]
For a prime $p$ with a divisibility witness and $n>0$:
$p$ is primitive for $F_n \iff (p \mid F_n \text{ and } z(p)=n).$
\end{theorem}

\begin{theorem}[Rigidity]
A value $p$ is a primitive divisor of at most one positive index: if $0<m$,
$0<n$, and $p$ is primitive for both $F_m$ and $F_n$, then $m=n$.
\end{theorem}

\begin{proof}[Proof sketch]
If $m<n$, primitivity at $n$ forbids $p \mid F_m$, contradicting primitivity at
$m$; symmetrically $n<m$ is impossible. Positivity is needed since every modulus
is vacuously primitive at index $0$ ($F_0=0$).
\end{proof}

\begin{theorem}[Apparition class]\label{thm:pin}
If $p$ is primitive for $F_n$ with $n>0$, then for all $m$:
$\;p \mid F_m \iff n \mid m.$
\end{theorem}

\section{Lifting the exponent for Fibonacci numbers}

Write $\vp(N)$ for the $p$-adic valuation of $N$.

\begin{lemma}[Multiplicativity]
For a prime $p$ and $a,b>0$: $\vp(ab)=\vp(a)+\vp(b)$.
\end{lemma}

\begin{lemma}[Ultrametric / tropical bound]
For a prime $p$ and $a,b>0$: $\min(\vp(a),\vp(b)) \le \vp(a+b)$.
\end{lemma}

\begin{theorem}[Fibonacci lifting-the-exponent]\label{thm:lte}
Let $p$ be an odd prime with $p \mid F_k$, $k>0$, and let $n>0$ with $p \nmid n$.
Then
\[
  \vp\!\big(F_{nk}\big) = \vp\!\big(F_k\big) + \vp(n).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Since $F_k \mid F_{nk}$, the quotient $Q_n=F_{nk}/F_k$ is an integer and
$\vp(F_{nk})=\vp(F_k)+\vp(Q_n)$. One proves by induction
\[
  Q_n \equiv n\, F_{k-1}^{\,n-1} \pmod p,
\]
via $F_{m+k}=F_m F_{k-1}+F_{m+1}F_k$ and $F_{mk+1}\equiv F_{k-1}^{\,m}\pmod p$.
Consecutive Fibonacci numbers are coprime, so $p \mid F_k$ gives $p \nmid
F_{k-1}$; with $p \nmid n$ this yields $p \nmid Q_n$, i.e.\ $\vp(Q_n)=0=\vp(n)$.
The full statement follows by the standard inductive lifting.
\end{proof}

\begin{remark}
By Theorem~\ref{thm:lte} the power of an \emph{old} prime in $F_n$ grows only like
$\vp(n)=O(\log n)$, whereas $F_n$ grows exponentially (Lemma~\ref{lem:exp}).
Hence the imprimitive part of $F_n$ is dwarfed by $F_n$ for large $n$, forcing a
primitive divisor.
\end{remark}

\section{The exceptional set and the prime-index case}

\begin{proposition}
$F_1$ and $F_2$ have no primitive prime divisor ($F_1=F_2=1$).
\end{proposition}

\begin{proposition}
$F_6=8$ has no primitive prime divisor: its only prime is $2$, and $2 \mid F_3$.
\end{proposition}

\begin{proposition}
$F_{12}=144=2^4\cdot 3^2$ has no primitive prime divisor: $2 \mid F_3$ and
$3 \mid F_4$.
\end{proposition}

\begin{proposition}
$F_3=2$, $F_4=3$, $F_5=5$, $F_7=13$ have primitive prime divisors $2,3,5,13$
respectively (and $F_8=21$ has $7$, $F_9=34$ has $17$, $F_{10}=55$ has $11$,
$F_{11}=89$ has $89$).
\end{proposition}

These together show the exceptional set is exactly $\{1,2,6,12\}$ and $13$ is the
sharp threshold.

\begin{theorem}[Carmichael for prime indices]\label{thm:prime}
If $p \ge 5$ is prime, then $F_p$ has a primitive prime divisor; indeed every
prime factor of $F_p$ is primitive.
\end{theorem}

\begin{proof}[Proof sketch]
The proper divisors of $p$ are $1$ and $p$; the only smaller index dividing $p$
is $1$, and $F_1=1$ has no prime factors. Since $F_p \ge p \ge 5>1$, $F_p$ has a
prime factor $q$. If $q \mid F_k$ for some $0<k<p$ then $q \mid \gcd(F_k,F_p)=
F_{\gcd(k,p)}=F_1=1$, a contradiction. Hence $q$ is primitive.
\end{proof}

\section{Localization of entry points via the companion matrix}

\begin{theorem}[Entry point divides $p^2-1$]\label{thm:loc}
For a prime $p \notin \{2,5\}$ there exists $k>0$ with $k \mid p^2-1$ and $p \mid
F_k$. In particular $z(p) \mid p^2-1$, hence $z(p) \le p^2-1$.
\end{theorem}

\begin{proof}[Proof sketch]
With $Q=\left(\begin{smallmatrix}1&1\\1&0\end{smallmatrix}\right)$ one has
$(Q^n)_{0,1}=F_n \pmod p$. Over $\overline{\mathbb{F}_p}$ the polynomial
$x^2-x-1$ has discriminant $5 \ne 0$ (as $p \ne 5$), so two distinct roots
$\alpha\ne\beta$ with $\alpha^2=\alpha+1$, $\beta^2=\beta+1$; thus $Q$ is
diagonalizable. The roots lie in $\mathbb{F}_{p^2}^\times$ of order $p^2-1$, so
$\alpha^{p^2-1}=\beta^{p^2-1}=1$, whence $Q^{p^2-1}=I$ and $F_{p^2-1}\equiv 0
\pmod p$. Take $k=p^2-1$; by Theorem~\ref{thm:char}, $z(p)\mid p^2-1$.
\end{proof}

\begin{remark}
Quadratic reciprocity refines this to $z(p) \mid p-\left(\tfrac{5}{p}\right)$,
giving $z(p)\le p+1$.
\end{remark}

\section{Simultaneous apparition}

\begin{theorem}[Two primitive divisors]
Let $p$ be primitive for $F_a$ and $q$ for $F_b$, $a,b>0$. Then for all $n$:
$\;(p \mid F_n \text{ and } q \mid F_n) \iff \lcm(a,b) \mid n.$
\end{theorem}

\begin{theorem}[Finite family]
Let $s$ be finite and, for each $i\in s$, $f_i$ primitive for $F_{g_i}$ with
$g_i>0$. Then for all $n$:
$\;(\forall i\in s,\ f_i \mid F_n) \iff \big(\lcm_{i\in s} g_i\big) \mid n.$
\end{theorem}

\begin{proof}[Proof sketch]
Apply Theorem~\ref{thm:pin} to each factor and combine via the lcm divisibility
law; the finite case is an induction over $s$ with $\lcm\varnothing=1$.
\end{proof}

\section{Algorithms, applications, and future work}

\subsection*{Algorithms}
(1) \emph{Entry-point search}: iterate $F_k \bmod p$ until $0$; terminates by
$k=p^2-1$ (Theorem~\ref{thm:loc}), in fact by $k=p+1$.
(2) \emph{Primitive-part certificate}: $\Pi_n=F_n/\gcd(F_n,\lcm_{d\mid n,d<n}F_d)$
(or $\Phi_n=\prod_{d\mid n}F_d^{\,\mu(n/d)}$); $\Pi_n>1$ certifies a primitive
divisor.
(3) \emph{Carmichael verification}: prime indices by Theorem~\ref{thm:prime};
composite by $\Pi_n>1$, valid for $n\ge 13$ via Lemma~\ref{lem:exp} versus
Theorem~\ref{thm:lte}.

\subsection*{Applications}
Lucas--Lehmer primality testing for Mersenne primes; Carmichael as prototype of
the Bang--Zsygmondy theorem for $a^n-b^n$, $2^n-1$, and Lucas sequences;
Diophantine bounds (Bilu--Hanrot--Voutier).

\subsection*{Future directions}

\begin{conjecture}[LTE, full form]
For an odd prime $p$ with $z(p)=m$ and any $k\ge 1$: $\vp(F_{mk})=\vp(F_m)+\vp(k)$.
\end{conjecture}

\begin{conjecture}[Primitive part dominates]
With $\Phi_n=\prod_{d\mid n}F_d^{\,\mu(n/d)}$, one has $\Phi_n>n$ for all $n\ge 13$.
\end{conjecture}

\begin{conjecture}[Entry-point localization]
For a prime $p\ne 5$, $z(p) \mid p-\left(\tfrac{5}{p}\right)$, hence $z(p)\le p+1$.
\end{conjecture}

\begin{conjecture}[Lucas analogue]
The Lucas numbers $L_n$ ($L_0=2$, $L_1=1$) have a primitive prime divisor for
every $n \notin \{1,6\}$.
\end{conjecture}

\begin{conjecture}[Multiplicity-one imprimitivity]
If $p \mid F_n$ is not primitive and is the largest such prime, then $p \mid n$
and $\vp(F_n)=\vp(F_{z(p)})+\vp(n)$.
\end{conjecture}

\section{Conclusion}

Anchored on strong divisibility, lifting-the-exponent, and exponential growth, we
obtained an unconditional proof of Carmichael's theorem for prime indices, a
sharp determination of the exceptional set $\{1,2,6,12\}$, the finite-field
localization $z(p)\mid p^2-1$, and the simultaneous-apparition calculus.
Carmichael's century-old theorem thereby appears as the clean prototype of the
general theory of primitive divisors in recurrence sequences.

\end{document}

