from math import gcd
from typing import List

def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def prime_factors(n: int) -> List[int]:
    f, d = [], 2
    while d * d <= n:
        if n % d == 0:
            f.append(d)
            while n % d == 0:
                n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        f.append(n)
    return f

def is_prime(p: int) -> bool:
    if p < 2: return False
    d = 2
    while d * d <= p:
        if p % d == 0: return False
        d += 1
    return True

def is_primitive(p: int, n: int) -> bool:
    if not is_prime(p) or fib(n) % p != 0:
        return False
    return all(fib(k) % p != 0 for k in range(1, n))

def primitive_divisors(n: int) -> List[int]:
    return [p for p in prime_factors(fib(n)) if is_primitive(p, n)]

print(f"{'n':>3} | {'F_n':>8} | factors            | primitive")
print("-" * 60)
for n in range(1, 21):
    pf = "*".join(map(str, prime_factors(fib(n)))) or "(none)"
    prim = ",".join(map(str, primitive_divisors(n))) or "NONE"
    print(f"{n:>3} | {fib(n):>8} | {pf:<18} | {prim}")

