function ENTRY_POINT(p):
    m <- p*p
    (a, b) <- (0, 1)              # (F_0, F_1) mod m
    for k = 1 to p*p - 1:
        (a, b) <- (b, (a + b) mod m)
        if a mod p == 0:
            return k             # z(p) = k
    fail  # unreachable for primes p != ... by localization theorem

function PRIMITIVE_PART(n):
    pi <- F_n
    if pi <= 1: return pi
    for each proper divisor d of n (d < n):
        g <- gcd(pi, F_d)
        while g > 1:
            pi <- pi / g
            g <- gcd(pi, F_d)
    return pi          # pi > 1  <=>  F_n has a primitive prime divisor

function FIB_VALUATION(p, n, z):   # z = entry point z(p)
    if n mod z != 0: return 0
    if p == 2: return v_2(F_n)       # 2 obeys a separate doubling rule
    return v_p(F_z) + v_p(n / z)

